import{z as i,x as l,o as B,c as d,q as A,j as t,D as a,d as n,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"金本位与大萧条","description":"","frontmatter":{"title":"金本位与大萧条","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gold-standard-depression.md","filePath":"econ/gold-standard-depression.md","lastUpdated":1791063341000}'),p={name:"econ/gold-standard-depression.md"};function D(C,E,h,m,c,F){const r=l("Mermaid");return B(),d("div",null,[E[2]||(E[2]=A('<h1 id="金本位与大萧条" tabindex="-1">金本位与大萧条 <a class="header-anchor" href="#金本位与大萧条" aria-label="Permalink to &quot;金本位与大萧条&quot;">​</a></h1><div class="epigraph"><p>金本位把汇率钉死、把货币政策绑在黄金，于是一国的紧缩经储备流失变成多国的通缩。早脱离金平价的经济更早再通胀——制度比编年更能解释为何萧条是全球的。</p><footer>—— Friedman and Schwartz, A Monetary History of the United States, 1963；Eichengreen, Golden Fetters, 1992；Bernanke, Essays on the Great Depression, 2000</footer></div><p><a href="/econ/pigouvian-carbon-price">上一课</a>把公共财政的加深层收在碳定价：SCC 定水平、Weitzman 判工具，EU ETS 与中国碳市场是同一逻辑的两种制度化。本课是<strong>经济史</strong>对照课的第一课；后课默认已经读完：危机用机制对照，不背年份表。缺口是：1929 年的美国股价与银行恐慌，如何变成十年的全球萧条。Friedman–Schwartz 钉住美联储让货币崩溃；Bernanke 补上金融加速器；Eichengreen 把金本位写成国际传导的枷锁。三句话要叠在一起，不能只留一句「股市崩了」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>钉住黄金：外部流失必须紧缩国内信用，否则平价不保。1920 年代末各国以扭曲的平价回到金本位，储备集中，规则不对称——盈余国不必膨胀，赤字国必须收缩。1929 年后美国信用收缩、银行倒闭，黄金与资本流动把通缩输出。名义工资与债务粘住，实际负担上升，破产与挤兑互相加强。缺口不是列出哪一年谁破产，而是：<strong>在浮动下可以各自再通胀的政策，在金本位下是「不负责任」</strong>；于是对称紧缩。英国 1931、美国 1933 脱离金本位后，工业与价格更早拐头——这是截面对照，不是故事高潮。</p><p><span class="marginnote">术语翻译：「金本位」就是法律规定 1 单位货币兑换固定克数的黄金，央行承诺按这个价无限买卖。两国货币因此互相钉死，汇率不再浮动。代价是：黄金流走，货币就必须收回，国内信贷跟着收缩——货币政策的主权让给了黄金的流向。</span></p><h3 id="大萧条不是「股市跌了所以十年」" tabindex="-1">大萧条不是「股市跌了所以十年」 <a class="header-anchor" href="#大萧条不是「股市跌了所以十年」" aria-label="Permalink to &quot;大萧条不是「股市跌了所以十年」&quot;">​</a></h3><p>股价是资产价格；十年萧条要货币、银行、债务通缩与国际制度。只讲 1929 年 10 月，会把因果收成市场情绪，并解释不了为何脱离金本位的时点预测复苏时点。银行倒闭摧毁的是信用中介，Bernanke 的加速器把这层从货币总量里拆出来：同样的 \\(M\\) 下降，金融摩擦让 \\(Y\\) 掉得更深。</p><p><span class="marginnote">数字实例：欠 1000 元债、物价水平为 100 时，实际负担就是 1000。通缩让物价跌到 90，工资收入缩水一成，但这 1000 元一分不能少——实际负担约变成 1111，凭空多出 11%。没有人做错任何事，全体负债人却同时变穷，这正是费雪说的债务通缩。</span></p><p><span class="marginnote">Bernanke 后来对 Friedman–Schwartz 的致敬，影响了 2008 年对银行与流动性的反应。史课对照的是机制是否可迁移，不是把 1930 年代当剧本重演。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层对照。(1) 货币：Friedman–Schwartz 的 \\(M\\) 崩溃与银行恐慌。(2) 金融加速器：净值下降 → 抵押与惜贷 → 投资消费再下降。(3) 金本位：固定汇率加黄金约束 = 输出通缩、禁止单独再通胀。政策实验是「何时脱离」：早脱离者更早 reflate。财政在金本位下也被「保卫平价」绑住，乘数课的工具集当时是空的。</p>',12)),(B(),t(o,null,{default:a(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PF%5B%22%E5%85%AC%E5%85%B1%E8%B4%A2%E6%94%BF%E6%94%B6%E6%9D%9F%22%5D%20--%3E%20GS%5B%22%E9%87%91%E6%9C%AC%E4%BD%8D%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20GS%20--%3E%20DEF%5B%22%E5%82%A8%E5%A4%87%E6%B5%81%E5%A4%B1%E5%BF%85%E9%A1%BB%E7%B4%A7%E7%BC%A9%22%5D%0A%20%20DEF%20--%3E%20ACC%5B%22%E5%80%BA%E5%8A%A1%E9%80%9A%E7%BC%A9%E4%B8%8E%E9%93%B6%E8%A1%8C%E5%8A%A0%E9%80%9F%E5%99%A8%22%5D%0A%20%20ACC%20--%3E%20EXIT%5B%22%E8%84%B1%E7%A6%BB%E9%87%91%E5%B9%B3%E4%BB%B7%E6%89%8D%E8%83%BD%E5%86%8D%E9%80%9A%E8%83%80%22%5D%0A%20%20EXIT%20--%3E%20BW%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E5%B8%83%E9%9B%B7%E9%A1%BF%E6%A3%AE%E6%9E%97%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"不要用战争赔款年表替代黄金约束；赔款是冲击，金本位是传导。银行倒闭的截面：更多依赖批发与房地产抵押的体系，加速器更陡——Bernanke 用各国银行结构解释深度差异，与「都是金本位」不矛盾：枷锁管广度，加速器管深度。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"机制是开放经济的三角在金本位下的极限：资本流动 + 固定平价 ⇒ 没有独立 \\(M\\)。通缩提高实际利率与实际债务，净值蒸发，银行挤兑——国内加速器与国际枷锁相乘。浮动后，\\(M\\) 可以扩张，价格预期扭转，加速器反号。这与后课布雷顿森林的「金汇兑」是同一金约束的不同松紧：那里美元居中，这里多国直接钉金。",-1)),(B(),t(o,null,{default:a(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E8%B5%A4%E5%AD%97%E5%9B%BD%EF%BC%9A%E8%B4%B8%E6%98%93%E4%B8%8E%E8%B5%84%E6%9C%AC%E5%A4%96%E6%B5%81%22%5D%20--%3E%20OUT%5B%22%E9%BB%84%E9%87%91%E5%82%A8%E5%A4%87%E6%B5%81%E5%A4%B1%22%5D%0A%20%20OUT%20--%3E%20TIGHT%5B%22%E4%B8%BA%E4%BF%9D%E5%B9%B3%E4%BB%B7%EF%BC%8C%E5%A4%AE%E8%A1%8C%E5%8A%A0%E6%81%AF%E3%80%81%E7%B4%A7%E7%BC%A9%E4%BF%A1%E7%94%A8%22%5D%0A%20%20TIGHT%20--%3E%20MDOWN%5B%22%E8%B4%A7%E5%B8%81%E4%B8%8E%E4%BF%A1%E8%B4%B7%E6%94%B6%E7%BC%A9%22%5D%0A%20%20MDOWN%20--%3E%20PDOWN%5B%22%E7%89%A9%E4%BB%B7%E4%B8%8B%E8%B7%8C%EF%BC%88%E9%80%9A%E7%BC%A9%EF%BC%89%22%5D%0A%20%20PDOWN%20--%3E%20REALDEBT%5B%22%E5%AE%9E%E9%99%85%E5%80%BA%E5%8A%A1%E8%B4%9F%E6%8B%85%E4%B8%8A%E5%8D%87%22%5D%0A%20%20REALDEBT%20--%3E%20DEFAULT%5B%22%E8%BF%9D%E7%BA%A6%E4%B8%8E%E9%93%B6%E8%A1%8C%E6%8C%A4%E5%85%91%22%5D%0A%20%20DEFAULT%20--%3E%7C%22%E9%80%9A%E7%BC%A9%E8%87%AA%E6%88%91%E5%8A%A0%E5%BC%BA%EF%BC%8C%E5%9B%9E%E5%88%B0%E8%B4%A7%E5%B8%81%E6%94%B6%E7%BC%A9%22%7C%20MDOWN%0A%20%20EXIT%5B%22%E5%AE%A3%E5%B8%83%E8%84%B1%E7%A6%BB%E9%87%91%E5%B9%B3%E4%BB%B7%22%5D%20-.-%3E%7C%22%E7%BB%95%E5%BC%80%E6%9E%B7%E9%94%81%22%7C%20REFL%5B%22%E8%B4%A7%E5%B8%81%E5%8F%AF%E6%89%A9%E5%BC%A0%EF%BC%8C%E9%A2%84%E6%9C%9F%E5%8F%8D%E8%BD%AC%EF%BC%8C%E6%9B%B4%E6%97%A9%E5%A4%8D%E8%8B%8F%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">常见误区：以为金本位是「稳健」的代名词、脱离是「耍赖」。历史记录相反：1930 年代坚持金本位越久，通缩与银行危机越深；英国 1931、美国 1933 脱离后工业产出与物价较快回升。坚守平价的「信誉」，是用国内就业与银行体系付的账。</span></p><p>与地方财政对照：地方不能印金（或印储备货币）；金本位下的主权也近似不能。层级不同，约束形状同族。金汇兑（部分储备）比纯金本位松一截，但仍把外部流失写成国内紧缩。后课布雷顿是把这一松一截制度化到美元身上。</p><p><span class="marginnote">Eichengreen, <em>Golden Fetters</em>：金本位不仅传导冲击，还通过信誉政治阻止国内稳定政策。早脱钩是政策选择，不是自然康复。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写交易策略，不进限价簿，不把每场银行倒闭列成编年。下一课：战后用美元–黄金重建固定汇率，松的是直接金本位，紧的是美元兑换承诺——Triffin 会把它拆掉。后课默认：大萧条的国际部分用金本位枷锁读；国内部分用货币崩溃加金融加速器读。不要只留股市。金平价若一开始就定错，枷锁在繁荣期已经在积压力，危机只是把约束写进价格。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课是经济史第一课；后课用制度对照，不堆编年。</li><li>金本位迫使对称紧缩，把一国通缩输出为全球萧条。</li><li>早脱离金平价者更早再通胀，是机制证据。</li><li>货币崩溃与银行加速器解释深度，金本位解释广度。</li><li>出处：Friedman and Schwartz 1963；Eichengreen 1992；Bernanke 2000。</li></ul>',7))])}const u=i(p,[["render",D]]);export{f as __pageData,u as default};
